 foreach(array("O'Reilly",str_repeat('x',26),'Missing')as$raw){$caught=false;try{ax_moderator($raw);}catch(PhpbbOwnedStorageFailure$e){$caught=true;}as_check($caught,'Native ambiguous/missing/overlength identity never resolves another owner');$count++;}
